#[test]
fn non_lowered_slot_loan_positions_rejected_e3104() { for (src, exp) in [("struct a { b int }\nfn main() {\n m := map[string]a{\"k\": a{b: 1}}\n var p = &m[\"k\"]\n fmt.println(p.b)\n}\n", Some("HYB-E3104")), ("struct a { b int }\nfn main() {\n m := map[string]a{\"k\": a{b: 1}}\n var p *a = &m[\"k\"]\n fmt.println(p.b)\n}\n", Some("HYB-E3104")), ("struct a { b int }\nfn main() {\n m := map[string]a{\"k\": a{b: 1}}\n ps := make([]*a, 1)\n ps[0] = &m[\"k\"]\n fmt.println(ps[0].b)\n}\n", Some("HYB-E3104")), ("struct a { b int }\nfn main() {\n m := map[string]a{\"k\": a{b: 1}}\n var q a = a{b: 0}\n xs := []int{0}\n q, xs[0] = &m[\"k\"], 1\n fmt.println(q.b, xs[0])\n}\n", Some("HYB-E3104")), ("struct a { b int }\nstruct box { p any }\nfn main() {\n m := map[string]a{\"k\": a{b: 1}}\n x := box{p: &m[\"k\"]}\n fmt.println(x.p)\n}\n", Some("HYB-E3104")), ("struct a { b int }\nstruct box { p any }\nfn main() {\n m := map[string]a{\"k\": a{b: 1}}\n x := box{p: 0}\n x.p = &m[\"k\"]\n fmt.println(x.p)\n}\n", Some("HYB-E3103")), ("struct a { b int }\nfn main() {\n m := map[string]a{\"k\": a{b: 1}}\n q := &m[\"k\"]\n q = &m[\"k\"]\n fmt.println(q.b)\n}\n", None)] { let r = hy_check::check_file(&hy_syntax::parse_file("t.hy", src).unwrap()); assert_eq!(r.diagnostics.iter().find(|d| d.severity == hy_diag::Severity::Error).map(|d| d.code.as_str()), exp, "{:?}", r.diagnostics); } }
